{"notes": "Light: lamp origin dark, walls+lamps block dark, glass overrides to own color, sensors+player transparent, crates opaque lit, overlaps union. Doors: sensor light string, open iff contains door letter. Move: walls/lamps/closed-doors/edge block, glass/sensor/open-door enterable. Push: dark crates immovable, lit crates slide far to obstacle/edge, player steps in. Testing lit vs dark, door move/light block, glass stack, color mixes, slide through glass/sensor/wall.", "hypotheses": [{"id": "H1", "statement": "Lamp ray starts next cell, origin dark, blocked dark by wall/lamp", "status": "supported", "evidence": "E-lamp-open, E-lamp-wall, T-block, M-walk"}, {"id": "H3", "statement": "Glass recolours beam to own color, stays lit, transmits", "status": "supported", "evidence": "E-glass, G-matrix"}, {"id": "H4", "statement": "Sensor reports cell light; door opens iff light contains door letter", "status": "supported", "evidence": "D-match, L-mix br opens red, w opens white"}, {"id": "H5", "statement": "Player transparent, crate opaque own-cell lit, lit=light non-empty, overlaps union sorted", "status": "supported", "evidence": "T-block, L-mix, E-crate-push"}, {"id": "H6", "statement": "Dark crates immovable; lit pushed crate slides to wall/lamp/crate/closed-door/edge, player follows one", "status": "supported", "evidence": "E-crate-push vs C-slide"}, {"id": "H7", "statement": "Player can enter glass/sensor/open-door/floor, blocked by wall/lamp/closed-door/crate", "status": "supported", "evidence": "M-walk, C-slide"}, {"id": "H8", "statement": "Doors transparent to light vs block; glass stack override; white mixing union", "status": "proposed", "evidence": "needs D-move-light, G-stack, L-mix2"}], "experiments": [{"id": "P-lit", "purpose": "lit crate push slides to edge", "layout": {"walls": [], "lamps": [{"x": 0, "y": 2, "color": "red", "dir": "E"}], "glass": [], "sensors": [], "doors": [], "player": {"x": 1, "y": 2}, "crates": [{"id": "a", "x": 2, "y": 2}]}, "actions": ["E"]}, {"id": "P-dark", "purpose": "dark crate push fails control", "layout": {"walls": [], "lamps": [{"x": 0, "y": 4, "color": "red", "dir": "E"}], "glass": [], "sensors": [], "doors": [], "player": {"x": 1, "y": 2}, "crates": [{"id": "a", "x": 2, "y": 2}]}, "actions": ["E"]}, {"id": "D-move-light", "purpose": "open vs closed door walk and light through doors", "layout": {"walls": [], "lamps": [{"x": 0, "y": 1, "color": "red", "dir": "E"}, {"x": 0, "y": 2, "color": "red", "dir": "E"}, {"x": 0, "y": 4, "color": "blue", "dir": "E"}], "glass": [], "sensors": [{"id": "s1", "x": 4, "y": 1}, {"id": "s3", "x": 5, "y": 1}, {"id": "s2", "x": 4, "y": 5}, {"id": "s4", "x": 5, "y": 5}], "doors": [{"id": "d1", "x": 1, "y": 3, "color": "red", "sensor": "s1"}, {"id": "d3", "x": 2, "y": 2, "color": "red", "sensor": "s3"}, {"id": "d2", "x": 3, "y": 3, "color": "red", "sensor": "s2"}, {"id": "d4", "x": 2, "y": 4, "color": "blue", "sensor": "s4"}], "player": {"x": 0, "y": 3}, "crates": []}, "actions": ["E", "E", "E", "E"]}, {"id": "G-stack", "purpose": "two glasses in series and white through green", "layout": {"walls": [], "lamps": [{"x": 0, "y": 3, "color": "red", "dir": "E"}, {"x": 0, "y": 4, "color": "white", "dir": "E"}, {"x": 0, "y": 0, "color": "white", "dir": "E"}], "glass": [{"x": 2, "y": 3, "color": "green"}, {"x": 4, "y": 3, "color": "blue"}, {"x": 2, "y": 4, "color": "green"}, {"x": 2, "y": 0, "color": "red"}], "sensors": [], "doors": [], "player": {"x": 6, "y": 6}, "crates": []}, "actions": ["N"]}, {"id": "L-mix2", "purpose": "overlap mixes and door contains with mixed light", "layout": {"walls": [], "lamps": [{"x": 0, "y": 1, "color": "red", "dir": "E"}, {"x": 6, "y": 1, "color": "green", "dir": "W"}, {"x": 0, "y": 2, "color": "white", "dir": "E"}, {"x": 6, "y": 2, "color": "red", "dir": "W"}, {"x": 0, "y": 3, "color": "blue", "dir": "E"}, {"x": 6, "y": 3, "color": "blue", "dir": "W"}], "glass": [], "sensors": [{"id": "s1", "x": 3, "y": 1}, {"id": "s2", "x": 3, "y": 2}, {"id": "s3", "x": 3, "y": 3}], "doors": [{"id": "d1", "x": 1, "y": 0, "color": "green", "sensor": "s1"}, {"id": "d2", "x": 2, "y": 0, "color": "white", "sensor": "s2"}, {"id": "d3", "x": 3, "y": 0, "color": "white", "sensor": "s3"}], "player": {"x": 6, "y": 6}, "crates": []}, "actions": ["N"]}, {"id": "C-trans", "purpose": "slide through glass sensor stopped by wall", "layout": {"walls": [{"x": 5, "y": 2}], "lamps": [{"x": 0, "y": 2, "color": "red", "dir": "E"}], "glass": [{"x": 3, "y": 2, "color": "green"}], "sensors": [{"id": "s1", "x": 4, "y": 2}], "doors": [{"id": "d1", "x": 6, "y": 0, "color": "red", "sensor": "s1"}], "player": {"x": 1, "y": 2}, "crates": [{"id": "a", "x": 2, "y": 2}]}, "actions": ["E"]}], "code": "function simulate(layout, actions){
  const colMap={red:'r',green:'g',blue:'b',white:'w'};
  const dirs={N:[0,-1],S:[0,1],E:[1,0],W:[-1,0]};
  const wallSet=new Set((layout.walls||[]).map(o=>o.x+','+o.y));
  const lampList=(layout.lamps||[]).map(o=>({x:o.x,y:o.y,c:colMap[o.color],dx:dirs[o.dir][0],dy:dirs[o.dir][1]}));
  const lampSet=new Set((layout.lamps||[]).map(o=>o.x+','+o.y));
  const glassMap=new Map((layout.glass||[]).map(o=>[o.x+','+o.y,colMap[o.color]]));
  const sensorList=(layout.sensors||[]).map(o=>({id:o.id,x:o.x,y:o.y}));
  const doorList=(layout.doors||[]).map(o=>({id:o.id,x:o.x,y:o.y,c:colMap[o.color],sensor:o.sensor}));
  const doorPosMap=new Map(doorList.map((d,i)=>[d.x+','+d.y,i]));
  let px=layout.player.x, py=layout.player.y;
  let crates=(layout.crates||[]).map(o=>({id:o.id,x:o.x,y:o.y}));
  function compute(){
    const crateSet=new Set(crates.map(c=>c.x+','+c.y));
    const sets=[];
    for(let y=0;y<7;y++){sets.push([]);for(let x=0;x<7;x++)sets[y].push(new Set());}
    for(const L of lampList){
      let cur=L.c;
      let x=L.x+L.dx, y=L.y+L.dy;
      while(x>=0&&x<7&&y>=0&&y<7){
        const key=x+','+y;
        if(wallSet.has(key)||lampSet.has(key)) break;
        if(glassMap.has(key)){
          const g=glassMap.get(key);
          sets[y][x].add(g);
          cur=g;
          if(crateSet.has(key)) break;
        } else {
          sets[y][x].add(cur);
          if(crateSet.has(key)) break;
        }
        x+=L.dx; y+=L.dy;
      }
    }
    const light=[];
    for(let y=0;y<7;y++){const row=[];for(let x=0;x<7;x++){const a=[...sets[y][x]].sort();row.push(a.join(''));}light.push(row);}
    const sensorObs=sensorList.map(s=>({id:s.id,light:light[s.y][s.x]}));
    const byId=new Map(sensorObs.map(o=>[o.id,o.light]));
    const doorObs=doorList.map(d=>{const sl=byId.get(d.sensor)||'';return {id:d.id,open:sl.includes(d.c)};});
    const openByPos=new Map();
    doorList.forEach((d,i)=>openByPos.set(d.x+','+d.y,doorObs[i].open));
    const crateObs=crates.map(c=>({id:c.id,x:c.x,y:c.y,lit:light[c.y][c.x]!==''}));
    return {light,sensorObs,doorObs,crateObs,openByPos};
  }
  const res=[];
  let c0=compute();
  res.push({player:{x:px,y:py},crates:c0.crateObs,light:c0.light,sensors:c0.sensorObs,doors:c0.doorObs});
  for(const a of actions){
    const cur=compute();
    const dv=dirs[a];
    const nx=px+dv[0], ny=py+dv[1];
    if(nx>=0&&nx<7&&ny>=0&&ny<7){
      const nk=nx+','+ny;
      const wBlock=wallSet.has(nk)||lampSet.has(nk);
      let dBlock=false;
      if(doorPosMap.has(nk)) dBlock=!cur.openByPos.get(nk);
      if(!wBlock&&!dBlock){
        const ci=crates.findIndex(cc=>cc.x===nx&&cc.y===ny);
        if(ci>=0){
          if(cur.crateObs[ci].lit){
            let tx=crates[ci].x, ty=crates[ci].y;
